queries.sparql:
PREFIX core: <https://cashtoss.info/ontology#>
PREFIX law: <https://cashtoss.info/ontology/law#>
PREFIX sr: <https://cashtoss.info/ontology/sr#>
PREFIX pen: <https://cashtoss.info/ontology/penalty#>
PREFIX guide: <https://cashtoss.info/ontology/guide#>
PREFIX risk: <https://cashtoss.info/ontology/risk#>
PREFIX haz: <https://cashtoss.info/ontology/risk/hazard#>
PREFIX ctx: <https://cashtoss.info/ontology/risk/context#>
PREFIX app: <https://cashtoss.info/ontology/app#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT DISTINCT ?hazard ?req1 ?req2 ?dependency
WHERE {
  ?req1 a sr:SafetyRequirement ;
        haz:targetsHazard ?hazard ;
        law:isBasedOnArticle ?a1 .

  ?req2 a sr:SafetyRequirement ;
        haz:targetsHazard ?hazard ;
        law:isBasedOnArticle ?a2 .

  FILTER(?req1 != ?req2)
  FILTER(?a1 != ?a2)

  OPTIONAL {
    ?req2 sr:hasDependencyFrom ?req1 ;
          sr:dependencyType ?dependency .
  }
  BIND(coalesce(?dependency, core:Dependency) AS ?dependency)
}
LIMIT 100

PREFIX app: <https://cashtoss.info/ontology/app#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX core: <https://cashtoss.info/ontology#>

SELECT
  ?hazardFinding
  ?findingStatus
  ?hazard
  ?penaltyExposureStatus
  ?penaltyRule
WHERE {
  ?hazardFinding rdf:type app:HazardFinding ;
                  app:hasFindingStatus ?findingStatus .

  OPTIONAL { ?hazardFinding app:judgesHazard ?hazard . }

  ?hazardFinding app:estimatesPenaltyExposure ?penaltyExposureStatus .

  OPTIONAL {
    ?penaltyExposureStatus app:basedOnPenaltyRule ?penaltyRule .
  }
}
LIMIT 100

PREFIX pen: <https://cashtoss.info/ontology/penalty#>
PREFIX app: <https://cashtoss.info/ontology/app#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT
  ?sanctionType
  ?penaltyExposureStatus
  ?penaltyRule
  ?severityScore
WHERE {
  ?penaltyExposureStatus rdf:type app:PenaltyExposureStatus ;
                           app:hasSanctionType ?sanctionType ;
                           app:basedOnPenaltyRule ?penaltyRule .

  OPTIONAL { ?penaltyRule pen:hasSeverityScore ?severityScore . }

  FILTER( EXISTS { ?penaltyRule pen:classifiesAsHighSeverity true } || EXISTS { ?penaltyRule pen:severityLabel "high" } )
}
LIMIT 100

PREFIX app: <https://cashtoss.info/ontology/app#>
PREFIX risk: <https://cashtoss.info/ontology/risk#>
PREFIX law: <https://cashtoss.info/ontology/law#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT
  ?correctiveActionPlan
  ?riskPattern
  ?article
WHERE {
  ?correctiveActionPlan rdf:type app:CorrectiveActionPlan ;
                           app:requiresBecauseOf ?riskPattern ;
                           app:hasRiskPattern ?riskPattern .

  ?riskPattern rdf:type risk:RiskPattern ;
                risk:basedOnArticle ?article .
}
LIMIT 100
